from collections import Counter
def solve(g):
    g=[row[:] for row in g]
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    H=len(g); W=len(g[0])
    m=bg  # background; markers are others
    for r in range(H):
        pts=[c for c,x in enumerate(g[r]) if x!=m]
        for a,b in zip(pts,pts[1:]):
            for c in range(a+1,b): g[r][c]=3
    for c in range(W):
        pts=[r for r,x in enumerate([row[c] for row in g]) if x!=m]
        for a,b in zip(pts,pts[1:]):
            for r in range(a+1,b): g[r][c]=3
    return g
